def doc(i,k,t,te,tf,tags,meta=None): return {"id":i,"kind":k,"title":t,"text":te,"fa":tf,"tags":tags,"meta":meta or {}}
prims=[doc("primitive:"+a,"primitive",b,c,d,e,{"primitive":a}) for a,b,c,d,e in P]
fams=[doc("family:"+a,"family",b,c,d,e,{"recipe":a}) for a,b,c,d,e in F]
snd=[doc(f"{k}:{i}",k,t,te,tf,tags,{k:i}) for k,i,t,te,tf,tags in M]
assert len(prims)==36 and len(fams)==27
for n,d in [("primitives.json",prims),("families.json",fams),("sounds.json",snd)]:
    json.dump(d, open(out+"/"+n,"w"), ensure_ascii=False, indent=0)
print(len(prims),len(fams),len(snd))
